    return { event: "", qualifier: `${subject} < ${pct}% HP` };
  }
  if (kind === "damageType") return { event: "", qualifier: `Damage: ${humanizeToken(gate?.a)}` };
  if (kind === "hasActionTag") return { event: "", qualifier: `Tag: ${humanizeToken(gate?.a)}` };

